ALTER TABLE public.transactions ADD COLUMN category text NOT NULL DEFAULT 'autres', ADD COLUMN operation_key text, ADD COLUMN world_at timestamptz;
CREATE UNIQUE INDEX transactions_operation_once ON public.transactions(account_id,operation_key) WHERE operation_key IS NOT NULL;
ALTER TABLE public.activities ADD COLUMN economy_payload jsonb NOT NULL DEFAULT '{}';
ALTER TABLE public.jobs ADD COLUMN economy_skill text, ADD COLUMN economy_level integer NOT NULL DEFAULT 0;
CREATE TABLE public.economy_catalog(id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK(kind IN('item','vehicle','training','housing')),category text NOT NULL, price integer NOT NULL CHECK(price>=0), duration_minutes integer NOT NULL DEFAULT 60 CHECK(duration_minutes>0), energy_cost integer NOT NULL DEFAULT 5 CHECK(energy_cost>=0), location_kind text NOT NULL DEFAULT 'commerce', config jsonb NOT NULL DEFAULT '{}',sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.economy_catalog TO authenticated; GRANT ALL ON public.economy_catalog TO service_role;
ALTER TABLE public.economy_catalog ENABLE ROW LEVEL SECURITY; CREATE POLICY catalog_read ON public.economy_catalog FOR SELECT TO authenticated USING(true);
CREATE TABLE public.economy_goals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),kind text NOT NULL CHECK(kind IN('saving','project')),target integer NOT NULL CHECK(target>0 AND target<=1000000),saved integer NOT NULL DEFAULT 0 CHECK(saved>=0),metric text NOT NULL DEFAULT 'cash',target_date date,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','achieved')),notified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT public.game_now(),request_id uuid NOT NULL,UNIQUE(character_id,request_id));
GRANT SELECT ON public.economy_goals TO authenticated; GRANT ALL ON public.economy_goals TO service_role;
ALTER TABLE public.economy_goals ENABLE ROW LEVEL SECURITY; CREATE POLICY goals_owner ON public.economy_goals FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.personal_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,catalog_id text NOT NULL REFERENCES public.economy_catalog(id),purchase_price integer NOT NULL CHECK(purchase_price>=0),condition text NOT NULL DEFAULT 'Bon état',acquired_at timestamptz NOT NULL DEFAULT public.game_now(),next_maintenance timestamptz,UNIQUE(character_id,catalog_id));
GRANT SELECT ON public.personal_assets TO authenticated; GRANT ALL ON public.personal_assets TO service_role;
ALTER TABLE public.personal_assets ENABLE ROW LEVEL SECURITY; CREATE POLICY assets_owner ON public.personal_assets FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.economy_operations(character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,operation_key text NOT NULL,kind text NOT NULL,amount integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'done' CHECK(status IN('done','failed')),payload jsonb NOT NULL DEFAULT '{}',occurred_at timestamptz NOT NULL DEFAULT public.game_now(),PRIMARY KEY(character_id,operation_key));
GRANT SELECT ON public.economy_operations TO authenticated; GRANT ALL ON public.economy_operations TO service_role;
ALTER TABLE public.economy_operations ENABLE ROW LEVEL SECURITY; CREATE POLICY operations_owner ON public.economy_operations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.personal_budgets(character_id uuid PRIMARY KEY REFERENCES public.characters(id) ON DELETE CASCADE,planned jsonb NOT NULL DEFAULT '{}',auto_rent boolean NOT NULL DEFAULT false,next_rent date,low_balance_notified boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.personal_budgets TO authenticated; GRANT ALL ON public.personal_budgets TO service_role;
ALTER TABLE public.personal_budgets ENABLE ROW LEVEL SECURITY; CREATE POLICY budgets_owner ON public.personal_budgets FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.career_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,kind text NOT NULL,label text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT public.game_now());
GRANT SELECT ON public.career_history TO authenticated; GRANT ALL ON public.career_history TO service_role;
ALTER TABLE public.career_history ENABLE ROW LEVEL SECURITY; CREATE POLICY career_owner ON public.career_history FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
COMMENT ON TABLE public.economy_operations IS 'Exactly-once personal economy operations; no municipal money access. Catalog prices are authoritative; personal rows are player read-only.';